const j=$input.first().json;
for(const k of ['job_id','working_title','production_brief','asset_manifest','footage_license','channel_id']) if(!j[k]) throw new Error(k+' required');
if(j.footage_license!=='owned_or_licensed'||!Array.isArray(j.asset_manifest)||!j.asset_manifest.length) throw new Error('rights-cleared asset manifest required');
return [{json:{job_id:j.job_id,idempotency_key:'youtube-outsourced:'+j.job_id,channel_id:j.channel_id,working_title:j.working_title,production_brief:j.production_brief,asset_manifest:j.asset_manifest.map(a=>({asset:a.asset,license:a.license,attribution:a.attribution||''})),freelancer_brief_status:'draft',acceptance_checks:['source rights','script fact check','audio intelligibility','visual QA','thumbnail rights','metadata originality'],delivery_status:'awaiting_human_vendor',upload_status:'draft_only',publish_enabled:false}}];
